import React, { useState, useEffect } from "react";
import "./SolovievPortfolio.css";

const images = [
  "/images/pic1.jpg",
  "/images/pic2.jpg",
  "/images/pic3.jpg",
  "/images/pic4.jpg",
  "/images/pic5.jpg",
];

function SolovievPortfolio() {
  const [index, setIndex] = useState(0);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % images.length);
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  const handleMouseMove = (e) => {
    const x = (e.clientX / window.innerWidth - 0.5) * 20;
    const y = (e.clientY / window.innerHeight - 0.5) * 20;
    setMousePos({ x, y });
  };

  return (
    <div className="portfolio-wrapper" onMouseMove={handleMouseMove}>
      {/* Фон */}
      <div className="interactive-bg">
        <div className="overlay"></div>

        {/* Карточки с картинками */}
        {images.map((img, i) => (
          <div
            key={i}
            className="image-card"
            style={{
              backgroundImage: `url(${img})`,
              opacity: i === index ? 1 : 0,
              transform: `translate(${mousePos.x / (i+1)}px, ${mousePos.y / (i+1)}px) scale(${i === index ? 1.05 : 1})`,
              zIndex: i === index ? 2 : 1,
            }}
          ></div>
        ))}

        {/* Центральный текст */}
        <div className="center-content">
          <h1 className="site-title">BUILDSY.RU</h1>
          <p className="site-subtitle">ИП Соловьёв Всеволод Александрович</p>
        </div>
      </div>

      {/* Разделы под слайдером */}
      <section className="blur-section about-section">
        <h2>О нас</h2>
        <p>
          Мы предоставляем профессиональные услуги по разработке и поддержке веб-сайтов. 
          Наша команда создаёт современные и функциональные решения для бизнеса любого уровня.
        </p>
      </section>

      <section className="blur-section contact-section">
        <h2>Контакты</h2>
        <p>📍 Адрес: г. Москва, ул. Примерная, д. 1</p>
        <p>📞 Телефон: +7 (999) 123-45-67</p>
        <p>✉ E-mail: info@buildsy.ru</p>
        <p>🌐 Сайт: <a href="https://buildsy.ru">buildsy.ru</a></p>
      </section>
    </div>
  );
}

export default SolovievPortfolio;
